            with (self.root/'data/postgresql.conf').open('a') as out:
                out.write("\nlisten_addresses=''\nunix_socket_directories='"+str(self.root)+"'\nport="+str(self.port)+"\nshared_buffers='8MB'\nmax_connections=50\nmax_worker_processes=4\nmax_parallel_workers=4\ndynamic_shared_memory_type=posix\nmin_dynamic_shared_memory=0\njit=off\nhuge_pages=off\nfsync=off\nfull_page_writes=off\nlog_min_messages=error\n")
            self.log=(self.root/'postgres.log').open('wb');self.process=subprocess.Popen([str(self.bin/'postgres'),'-D',str(self.root/'data')],stdout=self.log,stderr=self.log,start_new_session=True)
            library=ctypes.CDLL('/usr/lib/x86_64-linux-gnu/libpq.so.5');self.lib=library
            for name,restype,argtypes in [('PQconnectdb',ctypes.c_void_p,[ctypes.c_char_p]),('PQstatus',ctypes.c_int,[ctypes.c_void_p]),('PQerrorMessage',ctypes.c_char_p,[ctypes.c_void_p]),('PQfinish',None,[ctypes.c_void_p]),('PQexec',ctypes.c_void_p,[ctypes.c_void_p,ctypes.c_char_p]),('PQresultStatus',ctypes.c_int,[ctypes.c_void_p]),('PQresultErrorMessage',ctypes.c_char_p,[ctypes.c_void_p]),('PQresultErrorField',ctypes.c_char_p,[ctypes.c_void_p,ctypes.c_int]),('PQntuples',ctypes.c_int,[ctypes.c_void_p]),('PQnfields',ctypes.c_int,[ctypes.c_void_p]),('PQgetvalue',ctypes.c_char_p,[ctypes.c_void_p,ctypes.c_int,ctypes.c_int]),('PQgetisnull',ctypes.c_int,[ctypes.c_void_p,ctypes.c_int,ctypes.c_int]),('PQclear',None,[ctypes.c_void_p])]:
                function=getattr(library,name);function.restype=restype;function.argtypes=argtypes
